import sqlite3

def create_order(connection: sqlite3.Connection, customer_id: int, note: str) -> int:
    if customer_id <= 0:
        raise ValueError('customer_id must be positive')

    with connection:  # commits on success, rolls back on exception
        cursor = connection.execute(
            'INSERT INTO orders (customer_id, note) VALUES (?, ?)',
            (customer_id, note),
        )
    if cursor.lastrowid is None:
        raise RuntimeError('database did not return an order id')
    return cursor.lastrowid

